history.text:
Kamu adalah asisten refactor kode JavaScript. Tugasmu: TULIS ULANG (recode) potongan kode yang diberikan owner supaya strukturnya, penamaan variabel, dan gaya penulisannya 100% konsisten dengan konvensi file bot WhatsApp "alipai-cmd.js" berikut ini.

ATURAN WAJIB (jangan dilanggar):
1. Konteks eksekusi: kode ini akan ditempel sebagai SATU case di dalam "switch (command) { ... }" milik fungsi async utama bot. JANGAN tulis ulang function wrapper/module.exports, cukup isi case-nya saja.
2. Format case: "case 'namafitur': {\n ... \n}\nbreak" (pakai tanda kurung kurawal, dan tulis nama case dalam huruf kecil sesuai konteks fitur).
3. Variabel & fungsi yang SUDAH TERSEDIA di scope (pakai ini, JANGAN reimplementasi ulang, JANGAN reimport hal yang sudah pasti ada):
 - m.sender, m.chat, m.isGroup, m.isAdmin, m.pushName, m.quoted, m.key
 - isCreator (boolean, true kalau owner bot)
 - text / q (isi argumen command setelah nama command)
 - prefix, command
 - Reply(pesan) — fungsi kirim balasan cepat
 - isRegistered(m.sender) — cek user sudah daftar
 - checkLimit(m.sender, global.isPrem(m.sender), isCreator) — cek limit habis (return true = limit habis)
 - addLimit(m.sender, global.isPrem(m.sender), isCreator) — kurangi limit
 - global.mess.verifikasi, global.mess.limit, global.mess.owner, global.mess.group, global.mess.admin — pesan error baku, SELALU pakai "global.mess.xxx" (JANGAN PERNAH pakai "mess.xxx" tanpa global, itu bug ReferenceError di file ini)
 - alip.sendMessage(m.chat, {...}, { quoted: m }) — kirim pesan/media
 - alip.sendMessage(m.chat, { react: { text: '⏳', key: m.key } }) — kasih react emoji status proses
 - axios — sudah ke-require di top-level file, JANGAN require ulang kecuali memang perlu scoped lokal
4. Pola standar tiap case (ikuti kalau relevan dengan kode yang direcode):
 - Validasi akses dulu (isRegistered/checkLimit/isCreator/m.isGroup/m.isAdmin) sebelum proses inti
 - React "⏳" sebelum proses berat, react "✅" setelah sukses, react "❌" kalau gagal
 - Bungkus proses inti dalam try/catch, console.error di catch, dan Reply pesan error yang jelas ke user
 - addLimit dipanggil SETELAH validasi lolos, SEBELUM proses berat mulai
5. Jangan ubah LOGIKA INTI/tujuan fungsional dari kode yang diberikan -- yang diubah cuma cara penulisannya supaya kompatibel, bukan fiturnya diganti jadi lain.
6. OUTPUT WAJIB: balas HANYA dengan kode JavaScript hasil recode-nya saja. JANGAN kasih penjelasan, JANGAN bungkus pakai markdown code fence (```), JANGAN kasih komentar pembuka/penutup di luar kode.

Berikut kode yang harus di-recode:
case 'reviewpay':
case 'testreviewpay': {
 try {
 const {
 proto,
 generateWAMessageFromContent
 } = require('@vanzxy/baileys');

 const jid = m.chat;

 const message = generateWAMessageFromContent(
 jid,
 {
 viewOnceMessage: {
 message: {
 interactiveMessage:
 proto.Message.InteractiveMessage.create({

 body:
 proto.Message.InteractiveMessage.Body.create({
 text:
 '🧪 *REVIEW & PAY TEST*\n\n' +
 'Pengujian InteractiveMessage\n' +
 '`review_and_pay`'
 }),

 footer:
 proto.Message.InteractiveMessage.Footer.create({
 text: 'Alipai • Review & Pay'
 }),

 nativeFlowMessage:
 proto.Message.InteractiveMessage.NativeFlowMessage.create({

 buttons: [
 {
 name: 'review_and_pay',

 buttonParamsJson:
 JSON.stringify({
 reference_id:
 `REVIEW-${Date.now()}`,

 currency:
 'IDR',

 total_amount: {
 value: 10000,
 offset: 100
 },

 order: {
 status: 'pending',

 subtotal: {
 value: 10000,
 offset: 100
 },

 items: [
 {
 retailer_id:
 'test-product-001',

 name:
 'Produk Test',

 quantity: 1,

 amount: {
 value: 10000,
 offset: 100
 }
 }
 ]
 }
 })
 }
 ]
 })
 })
 }
 }
 },
 {
 userJid:
 alip.user?.id ||
 m.sender,

 quoted: m
 }
 );

 if (
 !message ||
 !message.message ||
 !message.key ||
 !message.key.id
 ) {
 throw new Error(
 'generateWAMessageFromContent menghasilkan message/key tidak valid'
 );
 }

 await alip.relayMessage(
 jid,
 message.message,
 {
 messageId: message.key.id
 }
 );

 console.log(
 '[REVIEW_AND_PAY] ✅ Berhasil di-relay:',
 message.key.id
 );

 } catch (err) {

 console.error(
 '[REVIEW_AND_PAY] ❌ ERROR:',
 err?.stack || err
 );

 await m.reply(
 '❌ *REVIEW_AND_PAY ERROR*\n\n' +
 '```' +
 (err?.message || String(err)) +
 '```'
 );
 }

 break;
}

case 'reviewpay':
case 'testreviewpay': {
  if (!isRegistered(m.sender)) {
    return Reply(global.mess.verifikasi);
  }
  if (checkLimit(m.sender, global.isPrem(m.sender), isCreator)) {
    return Reply(global.mess.limit);
  }

  await alip.sendMessage(m.chat, {
    react: {
      text: '⏳',
      key: m.key
    }
  });

  try {
    const {
      proto,
      generateWAMessageFromContent
    } = require('@whiskeysockets/baileys');

    const jid = m.chat;

    const message = generateWAMessageFromContent(
      jid, {
        viewOnceMessage: {
          message: {
            interactiveMessage: proto.Message.InteractiveMessage.create({
              body: proto.Message.InteractiveMessage.Body.create({
                text: '🧪 *REVIEW & PAY TEST*\n\nPengujian InteractiveMessage\n`review_and_pay`'
              }),
              footer: proto.Message.InteractiveMessage.Footer.create({
                text: 'Alipai • Review & Pay'
              }),
              nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.create({
                buttons: [{
                  name: 'review_and_pay',
                  buttonParamsJson: JSON.stringify({
                    reference_id: `REVIEW-${Date.now()}`,
                    currency: 'IDR',
                    total_amount: {
                      value: 10000,
                      offset: 100
                    },
                    order: {
                      status: 'pending',
                      subtotal: {
                        value: 10000,
                        offset: 100
                      },
                      items: [{
                        retailer_id: 'test-product-001',
                        name: 'Produk Test',
                        quantity: 1,
                        amount: {
                          value: 10000,
                          offset: 100
                        }
                      }]
                    }
                  })
                }]
              })
            })
          }
        }
      }, {
        userJid: alip.user?.id || m.sender,
        quoted: m
      }
    );

    if (!message || !message.message || !message.key || !message.key.id) {
      throw new Error('generateWAMessageFromContent menghasilkan message/key tidak valid');
    }

    await alip.relayMessage(jid, message.message, {
      messageId: message.key.id
    });

    console.log('[REVIEW_AND_PAY] ✅ Berhasil di-relay:', message.key.id);
    addLimit(m.sender, global.isPrem(m.sender), isCreator);

    await alip.sendMessage(m.chat, {
      react: {
        text: '✅',
        key: m.key
      }
    });

  } catch (err) {
    console.error('[REVIEW_AND_PAY] ❌ ERROR:', err?.stack || err);
    await m.reply('❌ *REVIEW_AND_PAY ERROR*\n\n' + '```' + (err?.message || String(err)) + '```');
    await alip.sendMessage(m.chat, {
      react: {
        text: '❌',
        key: m.key
      }
    });
  }
  break;
}
